import java.util.Date;

public class Foo {
    String bar(Object o) {
        return switch (o) {
            case Date d -> d.toString();
            default -> "";
        };
    }
}

import java.util.Date;

public class Foo {
    record Range(Date from, Date to) { }

    void bar(Object o) {
        if (o instanceof Range(Date from, Date to)) {
            System.out.println(from);
        }
    }
}

import java.time.LocalDateTime;

